/* eslint-disable */
// harjutaja service worker (generated by scripts/build-sw.mjs — do not edit the
// generated public/sw.js by hand). Versioned caches keyed by the build id, an
// offline app-shell fallback, and mutations are never cached.
const BUILD_ID = '__BUILD_ID__';
const PRECACHE = __PRECACHE__;
const STATIC_CACHE = 'harjutaja-static-' + BUILD_ID;
const SHELL_CACHE = 'harjutaja-shell-' + BUILD_ID;

// Child-facing shells warmed at install so they open with no network.
const SHELL_ROUTES = [
  '/', '/kiur', '/kirsi', '/test', '/history', '/offline',
  '/manifest.webmanifest',
  '/web-app-manifest-192x192.png',
  '/web-app-manifest-512x512.png'
];

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const staticCache = await caches.open(STATIC_CACHE);
    await Promise.allSettled(PRECACHE.map((url) => staticCache.add(url)));
    const shellCache = await caches.open(SHELL_CACHE);
    await Promise.allSettled(SHELL_ROUTES.map(async (route) => {
      try {
        const res = await fetch(route, { credentials: 'same-origin' });
        if (res.ok) await shellCache.put(route, res.clone());
      } catch (e) {
        /* offline prep tolerates individual failures */
      }
    }));
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(
      keys.filter((key) => key.startsWith('harjutaja-') && !key.endsWith(BUILD_ID)).map((key) => caches.delete(key))
    );
    await self.clients.claim();
  })());
});

// Activation is delayed until the app explicitly asks (so a new build never
// replaces the code mid-exercise).
self.addEventListener('message', (event) => {
  if (event.data === 'SKIP_WAITING') self.skipWaiting();
});

function isNavigationRequest(request) {
  return request.mode === 'navigate';
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return; // mutations are never cached
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname.startsWith('/api/')) return; // network-only; app handles offline via IndexedDB

  if (isNavigationRequest(request)) {
    // Network-first, fall back to the cached shell for that route, then /offline.
    event.respondWith((async () => {
      try {
        const res = await fetch(request);
        const shellCache = await caches.open(SHELL_CACHE);
        shellCache.put(request, res.clone()).catch(() => {});
        return res;
      } catch (e) {
        const shellCache = await caches.open(SHELL_CACHE);
        const cached = (await shellCache.match(request)) || (await shellCache.match(url.pathname)) || (await shellCache.match('/offline'));
        return cached || new Response('Offline', { status: 503, headers: { 'Content-Type': 'text/plain' } });
      }
    })());
    return;
  }

  // Static assets: cache-first with background revalidation.
  if (url.pathname.startsWith('/_next/static/') || /\.(?:js|css|png|jpg|jpeg|svg|webp|woff2?)$/.test(url.pathname)) {
    event.respondWith((async () => {
      const cache = await caches.open(STATIC_CACHE);
      const cached = await cache.match(request);
      const network = fetch(request)
        .then((res) => { if (res && res.ok) cache.put(request, res.clone()); return res; })
        .catch(() => null);
      return cached || (await network) || new Response('', { status: 504 });
    })());
  }
});
